INSERT INTO `levels` (`id`, `module_id`, `tier`, `slug`, `title_en`, `title_id`, `instructions_en`, `instructions_id`, `game_type`, `game_data`, `order`, `created_at`, `updated_at`) VALUES
	(1, 1, 'rookie', 'straight-line', 'Straight Line', 'Garis Lurus', 'Move the robot forward to reach the flag.', 'Gerakkan robot maju untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 4, "y": 1}, "start": {"x": 0, "y": 1, "dir": "right"}, "walls": [], "width": 5, "height": 3, "max_blocks": 8}', 1, '2026-10-05 02:20:49', '2026-10-12 00:46:16'),
	(2, 1, 'rookie', 'turn-corner', 'Turn the Corner', 'Belok di Sudut', 'Turn and move to reach the flag.', 'Belok dan bergerak untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 4, "y": 4}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "width": 5, "height": 5, "max_blocks": 12}', 2, '2026-10-05 02:20:49', '2026-10-12 00:46:16'),
	(3, 1, 'rookie', 'around-wall', 'Around the Wall', 'Melewati Dinding', 'Navigate around the wall to reach the flag.', 'Hindari dinding untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 4, "y": 2}, "start": {"x": 0, "y": 2, "dir": "right"}, "walls": [[2, 1], [2, 2], [2, 3]], "width": 5, "height": 5, "max_blocks": 15}', 3, '2026-10-05 02:20:49', '2026-10-12 00:46:16'),
	(4, 2, 'rookie', 'repeat-straight', 'Repeat and Walk', 'Ulangi dan Jalan', 'Use a loop to move forward 6 times.', 'Gunakan loop untuk maju 6 kali.', 'robot_path', '{"goal": {"x": 6, "y": 1}, "start": {"x": 0, "y": 1, "dir": "right"}, "walls": [], "width": 7, "height": 3, "max_blocks": 4, "allow_loops": true}', 1, '2026-10-05 20:18:58', '2026-10-12 00:46:16'),
	(5, 2, 'rookie', 'repeat-square', 'Square Path', 'Jalur Persegi', 'Use a loop to go around the square.', 'Gunakan loop untuk mengelilingi persegi.', 'robot_path', '{"goal": {"x": 0, "y": 0}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "width": 5, "height": 5, "max_blocks": 6, "allow_loops": true}', 2, '2026-10-05 20:18:58', '2026-10-12 00:46:16'),
	(6, 2, 'rookie', 'repeat-zigzag', 'Zigzag', 'Zig-zag', 'Repeat the pattern to reach the flag.', 'Ulangi pola untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 6, "y": 4}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "width": 7, "height": 5, "max_blocks": 8, "allow_loops": true}', 3, '2026-10-05 20:18:58', '2026-10-12 00:46:16'),
	(7, 3, 'rookie', 'straight-fix', 'Fix the Straight Path', 'Perbaiki Jalur Lurus', 'One block is wrong. Click it and pick the correct one so the robot reaches the flag.', 'Satu blok salah. Klik dan pilih yang benar agar robot mencapai bendera.', 'pattern_fixer', '{"goal": {"x": 4, "y": 1}, "start": {"x": 0, "y": 1, "dir": "right"}, "walls": [], "width": 5, "height": 3, "options": ["forward", "left", "right"], "program": [{"type": "forward"}, {"type": "forward"}, {"type": "left"}, {"type": "forward"}, {"type": "forward"}], "bug_index": 2}', 1, '2026-10-09 20:51:01', '2026-10-12 00:46:16'),
	(8, 3, 'rookie', 'turn-down', 'Turn Down', 'Belok ke Bawah', 'The robot needs to turn down to reach the flag. Fix the wrong block.', 'Robot harus belok ke bawah untuk mencapai bendera. Perbaiki blok yang salah.', 'pattern_fixer', '{"goal": {"x": 2, "y": 4}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "width": 3, "height": 5, "options": ["forward", "left", "right"], "program": [{"type": "forward"}, {"type": "forward"}, {"type": "left"}, {"type": "forward"}, {"type": "forward"}, {"type": "forward"}, {"type": "forward"}], "bug_index": 2}', 2, '2026-10-09 20:51:01', '2026-10-12 00:46:16'),
	(9, 3, 'rookie', 'down-to-flag', 'Down to the Flag', 'Turun ke Bendera', 'Fix the last block so the robot reaches the flag.', 'Perbaiki blok terakhir agar robot mencapai bendera.', 'pattern_fixer', '{"goal": {"x": 3, "y": 3}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [], "width": 4, "height": 4, "options": ["forward", "left", "right"], "program": [{"type": "forward"}, {"type": "forward"}, {"type": "forward"}, {"type": "right"}, {"type": "forward"}, {"type": "forward"}, {"type": "left"}], "bug_index": 6}', 3, '2026-10-09 20:51:01', '2026-10-12 00:46:16'),
	(10, 1, 'explorer', 'maze-turn', 'Maze Turn', 'Belokan Labirin', 'Navigate around the walls to reach the flag.', 'Hindari dinding untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 5, "y": 5}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [[2, 0], [2, 1], [2, 2], [3, 3], [4, 3]], "width": 6, "height": 6, "max_blocks": 15}', 10, '2026-10-12 00:46:16', '2026-10-12 00:46:16'),
	(11, 1, 'explorer', 'long-path', 'Long Path', 'Jalur Panjang', 'Plan carefully to reach the flag.', 'Rencanakan dengan hati-hati untuk mencapai bendera.', 'robot_path', '{"goal": {"x": 7, "y": 4}, "start": {"x": 0, "y": 0, "dir": "right"}, "walls": [[2, 1], [2, 2], [2, 3], [5, 1], [5, 2], [5, 3]], "width": 8, "height": 5, "max_blocks": 18}', 11, '2026-10-12 00:46:16', '2026-10-12 00:46:16'),
